# ── Metrics computation ──────────────────────────────────────────────

def compute_metrics(results: List[Dict]) -> Dict[str, float]:
    if not results:
        return {"R@1": 0.0, "R@5": 0.0, "MRR": 0.0, "count": 0}
    ranks = [r["rank"] for r in results]
    n = len(ranks)
    return {
        "R@1": sum(1 for r in ranks if r <= 1) / n,
        "R@5": sum(1 for r in ranks if r <= 5) / n,
        "MRR": sum(1.0 / r for r in ranks) / n,
        "count": n,
    }


def _metric_fn(results, metric_name):
    m = compute_metrics(results)
    return m[metric_name]


def bootstrap_ci(
    results: List[Dict],
    metric_name: str = "R@1",
    n_bootstrap: int = 1000,
    ci: float = 0.95,
    seed: int = 42,
) -> Tuple[float, float, float]:
    rng = np.random.RandomState(seed)
    n = len(results)
    if n == 0:
        return (0.0, 0.0, 0.0)

    point = _metric_fn(results, metric_name)
    boot_values = []
    for _ in range(n_bootstrap):
        idx = rng.choice(n, n, replace=True)
        boot_sample = [results[i] for i in idx]
        boot_values.append(_metric_fn(boot_sample, metric_name))

    alpha = (1 - ci) / 2
    lo = float(np.percentile(boot_values, alpha * 100))
    hi = float(np.percentile(boot_values, (1 - alpha) * 100))
    return (point, lo, hi)


